 try{var pending=CodexQuotaSnapshot.Parse(Response(null),now);Check(pending.Windows.Count==1&&pending.Remaining(300,now)==100,"fresh unused window with no reset timestamp retains remaining quota");Check(CodexQuotaReader.Countdown(pending,300,now).Contains("首次"),"unused window explicitly awaits first request");Check(TaskbarPainter.QuotaValue(pending,300,new TaskbarAppearance(),now).Contains("待启动"),"taskbar distinguishes pending cycle");}catch(Exception){Check(false,"fresh unused window with no timestamp must parse");}
