 var old=new CodexQuotaSnapshot{AccountKey="A",PlanType="pro",CheckedUtc=now.AddMinutes(-2)};old.Windows.Add(new CodexQuotaWindow{Minutes=10080,Remaining=20,ResetUtc=now.AddSeconds(-1)});var full=new CodexQuotaSnapshot{AccountKey="A",PlanType="pro",CheckedUtc=now};full.Windows.Add(new CodexQuotaWindow{Minutes=10080,Remaining=100,ResetUtc=now.AddDays(7)});var wake=new CodexWakeConfig();Check(wake.Reserve(full,old,now)==null&&wake.Attempts.Count==0,"auto wake disabled by default");wake.Enabled=true;Check(wake.Reserve(full,old,now)==null&&wake.CandidateKeys.Count==1&&wake.Attempts.Count==0,"first recovered reading only creates confirmation candidate");var full2=new JavaScriptSerializer().Deserialize<CodexQuotaSnapshot>(new JavaScriptSerializer().Serialize(full));full2.CheckedUtc=now.AddMinutes(1);full2.Windows[0].ResetUtc=now.AddMinutes(1).AddDays(7);Check(wake.Reserve(full2,full,full2.CheckedUtc)!=null&&wake.Attempts.Count==1,"second official reading reserves one request before execution");var persisted=new JavaScriptSerializer().Deserialize<CodexWakeConfig>(new JavaScriptSerializer().Serialize(wake));Check(persisted.Reserve(full2,full,full2.CheckedUtc)==null,"attempt survives restart without retry");full2.AccountKey="B";Check(new CodexWakeConfig{Enabled=true}.Reserve(full2,old,full2.CheckedUtc)==null,"account switch never auto wakes");full2.AccountKey="A";full2.PlanType="";Check(new CodexWakeConfig{Enabled=true}.Reserve(full2,old,full2.CheckedUtc)==null,"API key or unknown plan never auto wakes");full2.PlanType="pro";full2.RequiresAuthorization=true;Check(new CodexWakeConfig{Enabled=true}.Reserve(full2,old,full2.CheckedUtc)==null,"untrusted quota result cannot wake");full2.RequiresAuthorization=false;Check(full.Windows[0].PendingStart(now),"unused full length reset moving with sample time stays pending");Check(CodexQuotaReader.Countdown(full2,10080,full2.CheckedUtc).Contains("首次"),"moving unused reset does not fabricate anchored countdown");var repeatCfg=new CodexQuotaConfig{LastObserved=full};Check(new CodexQuotaReader().ObserveResets(full2,repeatCfg,full2.CheckedUtc).Length==0,"moving unused windows do not repeatedly announce reset");var recoveredCfg=new CodexQuotaConfig{LastObserved=old};var detected=new CodexQuotaReader().ObserveResets(full,recoveredCfg,now);Check(detected.Length==1&&detected[0].AwaitingStart,"quota recovery recorded separately from cycle start");Check(detected[0].Report().Contains("尚未启动"),"recovery history does not claim a fixed new reset time");string minimal=CodexQuotaReader.MinimalArguments("gpt-test-mini","low",@"C:\Temp\probe");Check(minimal.Contains("--ignore-user-config")&&minimal.Contains("--ephemeral")&&minimal.Contains("--disable shell_tool")&&minimal.Contains("project_doc_max_bytes=0"),"minimal request ignores projects tools and persistent chats");bool injected=false;try{CodexQuotaReader.MinimalArguments("bad;command","low",@"C:\Temp");}catch(ArgumentException){injected=true;}Check(injected,"model command injection rejected");Check(CodexQuotaReader.AccountPlan(new System.Collections.Generic.Dictionary<string,object>{{"account",new System.Collections.Generic.Dictionary<string,object>{{"type","chatgpt"},{"planType","pro"}}}})=="pro","official plan type parsed without guessing expiry");
 var catchup=new CodexWakeConfig{Enabled=true};Check(catchup.Reserve(full2,full,full2.CheckedUtc)==null&&catchup.CandidateKeys.Count==1,"already pending cycle creates catch-up candidate");var catchupNext=new JavaScriptSerializer().Deserialize<CodexQuotaSnapshot>(new JavaScriptSerializer().Serialize(full2));catchupNext.CheckedUtc=full2.CheckedUtc.AddMinutes(1);catchupNext.Windows[0].ResetUtc=catchupNext.CheckedUtc.AddDays(7);Check(catchup.Reserve(catchupNext,full2,catchupNext.CheckedUtc)!=null,"two pending readings trigger minimal-request catch-up");var catchupSaved=new JavaScriptSerializer().Deserialize<CodexWakeConfig>(new JavaScriptSerializer().Serialize(catchup));var later=new JavaScriptSerializer().Deserialize<CodexQuotaSnapshot>(new JavaScriptSerializer().Serialize(catchupNext));later.CheckedUtc=catchupNext.CheckedUtc.AddMinutes(20);later.Windows[0].ResetUtc=later.CheckedUtc.AddDays(7);Check(catchupSaved.Reserve(later,catchupNext,later.CheckedUtc)==null&&catchupSaved.Attempts.Count==1&&catchupSaved.CandidateKeys.Count==0,"rolling pending reset and restart do not repeat a spent catch-up");var active=new JavaScriptSerializer().Deserialize<CodexQuotaSnapshot>(new JavaScriptSerializer().Serialize(later));active.CheckedUtc=later.CheckedUtc.AddMinutes(1);active.Windows[0].Remaining=90;Check(catchupSaved.Reserve(active,later,active.CheckedUtc)==null,"active cycle clears pending episode without request");var nextCycle=new JavaScriptSerializer().Deserialize<CodexQuotaSnapshot>(new JavaScriptSerializer().Serialize(active));nextCycle.CheckedUtc=active.CheckedUtc.AddDays(7);nextCycle.Windows[0].Remaining=100;nextCycle.Windows[0].ResetUtc=nextCycle.CheckedUtc.AddDays(7);Check(catchupSaved.Reserve(nextCycle,active,nextCycle.CheckedUtc)==null&&catchupSaved.CandidateKeys.Count==1,"next recovered cycle can create a new candidate");var fiveOld=new CodexQuotaSnapshot{AccountKey="A",PlanType="pro",CheckedUtc=now};fiveOld.Windows.Add(new CodexQuotaWindow{Minutes=300,Remaining=100,ResetUtc=now.AddHours(5)});var fiveNew=new JavaScriptSerializer().Deserialize<CodexQuotaSnapshot>(new JavaScriptSerializer().Serialize(fiveOld));fiveNew.CheckedUtc=now.AddMinutes(1);fiveNew.Windows[0].ResetUtc=fiveNew.CheckedUtc.AddHours(5);Check(new CodexWakeConfig{Enabled=true,FiveHour=false}.Reserve(fiveNew,fiveOld,fiveNew.CheckedUtc)==null,"five-hour catch-up respects its own switch");var fiveWake=new CodexWakeConfig{Enabled=true,FiveHour=true};fiveWake.Reserve(fiveNew,fiveOld,fiveNew.CheckedUtc);Check(fiveWake.CandidateKeys.Count==1,"five-hour enabled pending cycle gets catch-up candidate");
 var pausedReader=new CodexQuotaReader();var pausedConfig=new CodexQuotaConfig{BackgroundRefresh=false};pausedReader.Sample(pausedConfig);System.Threading.Thread.Sleep(100);Check(!pausedReader.Sample(pausedConfig).RequiresAuthorization&&pausedReader.Status.Contains("等待"),"background switch prevents process launch");pausedReader.RefreshNow();pausedReader.Sample(pausedConfig);System.Threading.Thread.Sleep(200);Check(pausedReader.Sample(pausedConfig).RequiresAuthorization,"manual refresh remains available with background polling off");
 string originalKey=Environment.GetEnvironmentVariable("OPENAI_API_KEY");try{Environment.SetEnvironmentVariable("OPENAI_API_KEY","test-only-dummy");var method=typeof(CodexQuotaReader).GetMethod("RunMinimalRequest",System.Reflection.BindingFlags.NonPublic|System.Reflection.BindingFlags.Static);string result=(string)method.Invoke(null,new object[]{System.Diagnostics.Process.GetCurrentProcess().MainModule.FileName,Path.GetTempPath(),"gpt-test-mini","low"});Check(result.Contains("已完成"),"isolated fake CLI receives safe flags empty workspace and no API key");string failed=(string)method.Invoke(null,new object[]{System.Diagnostics.Process.GetCurrentProcess().MainModule.FileName,Path.GetTempPath(),"gpt-failing-mini","low"});Check(failed.Contains("23")&&failed.Contains("reserved built-in"),"CLI nonzero exit retains actionable config error");string failedStream=(string)method.Invoke(null,new object[]{System.Diagnostics.Process.GetCurrentProcess().MainModule.FileName,Path.GetTempPath(),"gpt-stream-failure-mini","low"});Check(!failedStream.Contains("已完成")&&failedStream.Contains("Unauthorized"),"failed JSON turn cannot be reported successful despite exit zero");Check(!failedStream.Contains("fixture-secret-value")&&!failedStream.Contains("user@example.com")&&!failedStream.Contains(@"C:\SyntheticProfile"),"wake diagnostics redact credentials email and personal paths");}finally{Environment.SetEnvironmentVariable("OPENAI_API_KEY",originalKey);}
